1	// ===== Estado global =====
2	const DIFFICULTY = {
3	    easy: { label: 'Fácil', maxGuesses: 9 },
4	    medium: { label: 'Média', maxGuesses: 7 },
5	    hard: { label: 'Difícil', maxGuesses: 5 }
6	};
7	const ROUND_SECONDS = 45;
8	
9	const state = {
10	    mode: localStorage.getItem('hangman.mode') || 'solo',
11	    difficulty: localStorage.getItem('hangman.difficulty') || 'medium',
12	    category: 'all',
13	    soundOn: localStorage.getItem('hangman.sound') !== 'off',
14	    theme: localStorage.getItem('hangman.theme') || 'light',
15	    selectedWord: '',
16	    hint: '',
17	    guessed: [],
18	    wrong: 0,
19	    maxGuesses: DIFFICULTY.medium.maxGuesses,
20	    active: false,
21	    result: null,
22	    currentTurn: 0,
23	    roundDraws: 0,
24	    timerId: null,
25	    timeLeft: 0,
26	    hintUsed: false
27	};
28	
29	// ===== DOM =====
30	const wordDisplayElement = document.getElementById('wordDisplay');
31	const guessesElement = document.getElementById('guesses');
32	const messageElement = document.getElementById('message');
33	const newGameBtn = document.getElementById('newGameBtn');
34	const keyElements = Array.from(document.querySelectorAll('.key'));
35	const fireworksCanvas = document.getElementById('fireworksCanvas');
36	const categorySelect = document.getElementById('categorySelect');
37	const scoreboard = document.getElementById('scoreboard');
38	const roundText = document.getElementById('roundText');
39	const timerText = document.getElementById('timerText');
40	const hintBtn = document.getElementById('hintBtn');
41	const revealBtn = document.getElementById('revealBtn');
42	const hintText = document.getElementById('hintText');
43	const themeToggle = document.getElementById('themeToggle');
44	const soundToggle = document.getElementById('soundToggle');
45	
46	// ===== Áudio (Web Audio API) =====
47	let audioCtx = null;
48	
49	function ensureAudio() {
50	    if (!audioCtx) {
51	        try {
52	            audioCtx = new (window.AudioContext || window.webkitAudioContext)();
53	        } catch (e) {
54	            audioCtx = null;
55	        }
56	    }
57	    if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
58	}
59	
60	function tone(freq, duration, delay, type = 'sine', gainValue = 0.12) {
61	    if (!state.soundOn || !audioCtx) return;
62	    const start = audioCtx.currentTime + delay;
63	    const osc = audioCtx.createOscillator();
64	    const gain = audioCtx.createGain();
65	    osc.type = type;
66	    osc.frequency.value = freq;
67	    gain.gain.setValueAtTime(gainValue, start);
68	    gain.gain.exponentialRampToValueAtTime(0.001, start + duration);
69	    osc.connect(gain).connect(audioCtx.destination);
70	    osc.start(start);
71	    osc.stop(start + duration);
72	}
73	
74	function playCorrect() { ensureAudio(); tone(520, 0.12, 0); tone(660, 0.15, 0.08); }
75	function playWrong() { ensureAudio(); tone(160, 0.25, 0, 'square', 0.08); }
76	function playWin() {
77	    ensureAudio();
78	    [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.22, i * 0.13, 'triangle', 0.14));
79	}
80	function playLose() {
81	    ensureAudio();
82	    [392, 330, 262, 196].forEach((f, i) => tone(f, 0.25, i * 0.15, 'sawtooth', 0.07));
83	}
84	
85	// ===== Placar (localStorage) =====
86	function loadScore(key, fallback) {
87	    try {
88	        const raw = localStorage.getItem(key);
89	        return raw ? JSON.parse(raw) : fallback;
90	    } catch (e) {
91	        return fallback;
92	    }
93	}
94	
95	function saveScore(key, value) {
96	    try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) { /* modo privado */ }
97	}
98	
99	const soloFallback = { wins: 0, losses: 0, streak: 0, bestStreak: 0, draws: 0 };
100	let soloScore = loadScore('hangman.solo', soloFallback);
101	let duelScore = loadScore('hangman.duel', { p1: 0, p2: 0, draws: 0 });
102	
103	function renderScoreboard() {
104	    scoreboard.innerHTML = '';
105	    if (state.mode === 'solo') {
106	        const cards = [
107	            { name: 'Vitórias', value: soloScore.wins },
108	            { name: 'Derrotas', value: soloScore.losses },
109	            { name: 'Sequência', value: soloScore.streak },
110	            { name: 'Recorde', value: soloScore.bestStreak }
111	        ];
112	        cards.forEach(c => {
113	            const div = document.createElement('div');
114	            div.className = 'score-card';
115	            div.innerHTML = `<div class="name">${c.name}</div><div class="score-value">${c.value}</div>`;
116	            scoreboard.appendChild(div);
117	        });
118	    } else {
119	        const cards = [
120	            { name: 'Jogador 1', value: duelScore.p1, turn: state.currentTurn === 0 },
121	            { name: 'Jogador 2', value: duelScore.p2, turn: state.currentTurn === 1 },
122	            { name: 'Empates', value: duelScore.draws }
123	        ];
124	        cards.forEach(c => {
125	            const div = document.createElement('div');
126	            div.className = 'score-card' + (c.turn ? ' turn' : '');
127	            div.innerHTML = `<div class="name">${c.name}</div><div class="score-value">${c.value}</div>`;
128	            scoreboard.appendChild(div);
129	        });
130	    }
131	}
132	
133	// ===== Palavras =====
134	function buildCategoryOptions() {
135	    const options = ['all'].concat(HangmanWordList.categoryList);
136	    categorySelect.innerHTML = '';
137	    options.forEach(opt => {
138	        const el = document.createElement('option');
139	        el.value = opt;
140	        el.textContent = opt === 'all' ? 'Todas' : HangmanWordList.categoryList.find(c => c.toLowerCase() === opt);
141	        categorySelect.appendChild(el);
142	    });
143	}
144	
145	function pickWord() {
146	    let pool = HangmanWordList.words;
147	    if (state.category !== 'all') {
148	        pool = pool.filter(w => w.category.toLowerCase() === state.category);
149	    }
150	    const unique = [];
151	    const seen = new Set();
152	    for (const w of pool) {
153	        if (!seen.has(w.word)) { seen.add(w.word); unique.push(w); }
154	    }
155	    return unique[Math.floor(Math.random() * unique.length)];
156	}
157	
158	// ===== Desenho da forca =====
159	// Corda, cabeça, tronco, 2 braços e 2 pernas = 7 partes
160	const hangmanParts = ['rope', 'head', 'body', 'leftArm', 'rightArm', 'leftLeg', 'rightLeg'];
161	
162	function drawHangmanPart() {
163	    // Re-rendere conforme o nº de erros, animando cada parte com CSS
164	    hangmanParts.forEach((id, i) => {
165	        const el = document.getElementById(id);
166	        if (i < state.wrong) {
167	            if (!el.classList.contains('drawn')) {
168	                requestAnimationFrame(() => el.classList.add('drawn'));
169	            }
170	        } else {
171	            el.classList.remove('drawn');
172	        }
173	    });
174	    updateFace();
175	}
176	
177	function resetHangman() {
178	    hangmanParts.forEach(id => document.getElementById(id).classList.remove('drawn'));
179	    face.classList.remove('visible', 'dead', 'fear', 'win', 'tired', 'talking');
180	    setBrows('relaxed');
181	    document.getElementById('mouth').setAttribute('d', MOUTHS.happy);
182	    [eyeL, eyeR].forEach(eye => {
183	        const pupil = eye.querySelector('.pupil');
184	        if (pupil) pupil.style.transform = '';
185	        eye.classList.remove('blink');
186	    });
187	}
188	
189	// ===== Expressões do stickman =====
190	const face = document.getElementById('face');
191	const eyeL = document.getElementById('eyeL');
192	const eyeR = document.getElementById('eyeR');
193	const browL = document.getElementById('browL');
194	const browR = document.getElementById('browR');
195	let blinkInterval = null;
196	let lookTimer = null;
197	let talkTimeout = null;
198	
199	const MOUTHS = {
200	    happy: 'M133 90 Q140 97 147 90',
201	    neutral: 'M134 92 Q140 93 146 92',
202	    worried: 'M134 93 Q140 91 146 93',
203	    scared: 'M138 89 Q140 99 142 89',
204	    dead: 'M134 93 Q140 90 146 93'
205	};
206	
207	const BROWS = {
208	    relaxed:      { l: 'M128 73 Q133 69 138 73', r: 'M142 73 Q147 69 152 73' },
209	    tired:        { l: 'M128 74 Q133 72.5 138 73.5', r: 'M142 73.5 Q147 72.5 152 74' },
210	    worried:      { l: 'M128 74.5 Q133 72 138 74', r: 'M142 74 Q147 72 152 74.5' },
211	    scared:       { l: 'M128 71.5 Q133 73 138 71.5', r: 'M142 71.5 Q147 73 152 71.5' }
212	};
213	
214	function setBrows(expr) {
215	    if (!BROWS[expr]) return;
216	    browL.setAttribute('d', BROWS[expr].l);
217	    browR.setAttribute('d', BROWS[expr].r);
218	}
219	
220	function updateFace() {
221	    if (!face) return;
222	    const headDrawn = document.getElementById('head').classList.contains('drawn');
223	    const ratio = state.maxGuesses > 0 ? state.wrong / state.maxGuesses : 0;
224	
225	    face.classList.remove('win', 'fear', 'dead', 'tired');
226	
227	    if (!headDrawn) {
228	        face.classList.remove('visible');
229	        return;
230	    }
231	    face.classList.add('visible');
232	
233	    if (state.result === 'win') {
234	        // Vitória: relaxa
235	        setBrows('relaxed');
236	        document.getElementById('mouth').setAttribute('d', MOUTHS.happy);
237	        face.classList.add('win');
238	        return;
239	    }
240	
241	    if (state.result === 'lose' || state.wrong >= state.maxGuesses) {
242	        setBrows('relaxed');
243	        state.result = 'lose';
244	        document.getElementById('mouth').setAttribute('d', MOUTHS.dead);
245	        face.classList.add('dead');
246	        [eyeL, eyeR].forEach(eye => {
247	            const pupil = eye.querySelector('.pupil');
248	            if (pupil) pupil.style.transform = '';
249	        });
250	        return;
251	    }
252	
253	    // Jogando: a expressão piora conforme perde tentativas
254	    if (ratio >= 0.7) {
255	        setBrows('scared');
256	        document.getElementById('mouth').setAttribute('d', MOUTHS.scared);
257	        face.classList.add('fear');
258	    } else if (ratio >= 0.45) {
259	        setBrows('worried');
260	        document.getElementById('mouth').setAttribute('d', MOUTHS.worried);
261	        face.classList.add('fear');
262	    } else if (ratio >= 0.28) {
263	        setBrows('tired');
264	        document.getElementById('mouth').setAttribute('d', MOUTHS.neutral);
265	        face.classList.add('tired');
266	    } else {
267	        setBrows('relaxed');
268	        document.getElementById('mouth').setAttribute('d', MOUTHS.happy);
269	    }
270	}
271	
272	function talkFace() {
273	    if (!face) return;
274	    face.classList.add('talking');
275	    clearTimeout(talkTimeout);
276	    talkTimeout = setTimeout(() => face.classList.remove('talking'), 1600);
277	}
278	
279	// Piscadas periódicas
280	function startBlinking() {
281	    if (blinkInterval) return;
282	    blinkInterval = true;
283	    let next = 2200;
284	    const schedule = () => {
285	        setTimeout(() => {
286	            if (!face.classList.contains('dead')) {
287	                eyeL.classList.add('blink');
288	                eyeR.classList.add('blink');
289	                setTimeout(() => {
290	                    eyeL.classList.remove('blink');
291	                    eyeR.classList.remove('blink');
292	                }, 130);
293	            }
294	            next = 1800 + Math.random() * 3400;
295	            schedule();
296	        }, next);
297	    };
298	    schedule();
299	}
300	
301	// Pupila segue o mouse enquanto está vivo
302	function startEyeFollowing() {
303	    if (lookTimer) return;
304	    lookTimer = document.addEventListener('mousemove', (e) => {
305	        if (face.classList.contains('dead') || !face.classList.contains('visible')) return;
306	        const eyes = [eyeL, eyeR];
307	        for (const eye of eyes) {
308	            const pupil = eye.querySelector('.pupil');
309	            if (!pupil) continue;
310	            const rect = eye.getBoundingClientRect();
311	            if (rect.width === 0) continue;
312	            const dx = e.clientX - (rect.left + rect.width / 2);
313	            const dy = e.clientY - (rect.top + rect.height / 2);
314	            const dist = Math.hypot(dx, dy);
315	            if (dist < 220) {
316	                const max = 2.6;
317	                const t = dist / 220;
318	                pupil.style.transform = `translate(${(dx / dist) * max * t}px, ${(dy / dist) * max * t}px)`;
319	            } else {
320	                pupil.style.transform = '';
321	            }
322	        }
323	    });
324	}
325	
326	// ===== Jogo =====
327	function displayWord() {
328	    let display = '';
329	    for (const ch of state.selectedWord) {
330	        display += state.guessed.includes(ch) ? ch + ' ' : '_ ';
331	    }
332	    wordDisplayElement.textContent = display.trim();
333	}
334	
335	function isWin() {
336	    return state.selectedWord.split('').every(ch => state.guessed.includes(ch));
337	}
338	
339	function remainingLettersInWord() {
340	    const inWord = new Set(state.selectedWord.split(''));
341	    return [...inWord].filter(ch => !state.guessed.includes(ch));
342	}
343	
344	function updateRevealBtn() {
345	    revealBtn.disabled = !state.active || remainingLettersInWord().length === 0 || state.wrong >= state.maxGuesses;
346	}
347	
348	function hint() {
349	    if (!state.active || state.hintUsed) return;
350	    state.hintUsed = true;
351	    hintText.textContent = `Dica: ${state.hint}`;
352	    hintBtn.disabled = true;
353	    talkFace();
354	}
355	
356	function revealLetter() {
357	    if (!state.active || state.wrong >= state.maxGuesses) return;
358	    const options = remainingLettersInWord();
359	    if (options.length === 0) return;
360	    const letter = options[Math.floor(Math.random() * options.length)];
361	    state.guessed.push(letter);
362	    state.wrong++;
363	    guessesElement.textContent = state.maxGuesses - state.wrong;
364	    drawHangmanPart();
365	    displayWord();
366	    markKey(letter, 'correct', true);
367	    playWrong();
368	    messageElSoft('Letra revelada por -1 tentativa.');
369	    if (isWin()) { endRound(true, state.currentTurn); return; }
370	    if (state.wrong >= state.maxGuesses) { endRound(false, null); return; }
371	    if (state.mode === 'duel') { switchTurn(); }
372	    updateRevealBtn();
373	}
374	
375	function markKey(letter, cls, disabled) {
376	    keyElements.forEach(key => {
377	        if (key.dataset.letter === letter) {
378	            key.classList.add(cls);
379	            key.disabled = disabled;
380	        }
381	    });
382	}
383	
384	function messageElSoft(text) {
385	    messageElement.textContent = text;
386	    messageElement.style.color = '';
387	}
388	
389	function switchTurn() {
390	    state.currentTurn = state.currentTurn === 0 ? 1 : 0;
391	    renderScoreboard();
392	    updateRoundInfo();
393	}
394	
395	function updateRoundInfo() {
396	    if (state.mode === 'duel') {
397	        const name = state.currentTurn === 0 ? 'Jogador 1' : 'Jogador 2';
398	        roundText.textContent = state.active ? `Vez de ${name}` : 'Rodada finalizada';
399	    } else {
400	        roundText.textContent = `Dificuldade: ${DIFFICULTY[state.difficulty].label} • ${state.category === 'all' ? 'Todas as categorias' : HangmanWordList.categoryList.find(c => c.toLowerCase() === state.category)}`;
401	    }
402	}
403	
404	function startTimer() {
405	    if (state.timerId) clearInterval(state.timerId);
406	    state.timeLeft = ROUND_SECONDS;
407	    renderTimer();
408	    state.timerId = setInterval(() => {
409	        state.timeLeft--;
410	        renderTimer();
411	        if (state.timeLeft <= 0) {
412	            if (state.mode === 'duel') {
413	                if (state.wrong >= state.maxGuesses) { endRound(false, null); return; }
414	                switchTurn();
415	                startTimer();
416	            } else {
417	                state.timeLeft = ROUND_SECONDS;
418	            }
419	        }
420	    }, 1000);
421	}
422	
423	function stopTimer() {
424	    if (state.timerId) { clearInterval(state.timerId); state.timerId = null; }
425	}
426	
427	function renderTimer() {
428	    timerText.textContent = `⏱ ${Math.max(0, state.timeLeft)}s`;
429	}
430	
431	function handleGuess(letter) {
432	    if (!state.active || state.guessed.includes(letter)) return;
433	
434	    state.guessed.push(letter);
435	    const correct = state.selectedWord.includes(letter);
436	    markKey(letter, correct ? 'correct' : 'incorrect', true);
437	    displayWord();
438	
439	    if (correct) {
440	        playCorrect();
441	        if (isWin()) {
442	            endRound(true, state.currentTurn);
443	            return;
444	        }
445	        // Acerto não consome a vez no modo duelo (quem acertou continua)
446	        updateRevealBtn();
447	        return;
448	    }
449	
450	    state.wrong++;
451	    guessesElement.textContent = state.maxGuesses - state.wrong;
452	    drawHangmanPart();
453	    playWrong();
454	    if (state.wrong >= state.maxGuesses) {
455	        endRound(false, null);
456	        return;
457	    }
458	    if (state.mode === 'duel') {
459	        switchTurn();
460	        startTimer();
461	    }
462	    updateRevealBtn();
463	}
464	
465	function endRound(won, winnerTurn) {
466	    state.active = false;
467	    state.result = won ? 'win' : 'lose';
468	    stopTimer();
469	    keyElements.forEach(key => key.disabled = true);
470	    hintBtn.disabled = true;
471	    revealBtn.disabled = true;
472	
473	    if (won) {
474	        playWin();
475	        if (state.mode === 'solo') {
476	            soloScore.wins++;
477	            soloScore.streak++;
478	            if (soloScore.streak > soloScore.bestStreak) soloScore.bestStreak = soloScore.streak;
479	            saveScore('hangman.solo', soloScore);
480	            messageElement.textContent = 'Parabéns! Você venceu!';
481	        } else {
482	            if (winnerTurn === 0) duelScore.p1++; else duelScore.p2++;
483	            saveScore('hangman.duel', duelScore);
484	            const name = winnerTurn === 0 ? 'Jogador 1' : 'Jogador 2';
485	            messageElement.textContent = `Parabéns! ${name} venceu!`;
486	        }
487	        messageElement.style.color = 'var(--correct)';
488	        triggerFireworks();
489	        updateFace();
490	    } else {
491	        playLose();
492	        if (state.mode === 'solo') {
493	            soloScore.losses++;
494	            soloScore.streak = 0;
495	            saveScore('hangman.solo', soloScore);
496	        } else {
497	            duelScore.draws++;
498	            saveScore('hangman.duel', duelScore);
499	        }
500	        messageElement.textContent = `Fim das tentativas! A palavra era: ${state.selectedWord}. Dica: ${state.hint}`;
501	        messageElement.style.color = 'var(--incorrect)';
502	        updateFace();
503	    }
504	
505	    // Revela a palavra no display
506	    state.guessed = [...new Set(state.selectedWord.split(''))];
507	    displayWord();
508	    keyElements.forEach(key => {
509	        const l = key.dataset.letter;
510	        if (state.selectedWord.includes(l)) {
511	            key.classList.remove('incorrect');
512	            key.classList.add('correct');
513	        }
514	    });
515	
516	    newGameBtn.textContent = state.mode === 'duel' ? 'Nova Rodada' : 'Novo Jogo';
517	    renderScoreboard();
518	    updateRoundInfo();
519	}
520	
521	function initRound(startTurn) {
522	    stopTimer();
523	    const chosen = pickWord();
524	    state.selectedWord = chosen.word.toUpperCase();
525	    state.hint = chosen.hint;
526	    state.guessed = [];
527	    state.wrong = 0;
528	    state.maxGuesses = DIFFICULTY[state.difficulty].maxGuesses;
529	    state.active = true;
530	    state.result = null;
531	    state.hintUsed = false;
532	    if (startTurn !== undefined) state.currentTurn = startTurn % 2;
533	
534	    guessesElement.textContent = state.maxGuesses;
535	    messageElement.textContent = '';
536	    hintText.textContent = '';
537	    hintBtn.disabled = false;
538	    categorySelect.disabled = false;
539	    displayWord();
540	    resetHangman();
541	    keyElements.forEach(key => {
542	        key.disabled = false;
543	        key.classList.remove('correct', 'incorrect');
544	    });
545	    fireworksCanvas.style.display = 'none';
546	    if (fireworkEngine) fireworkEngine.stop();
547	    updateRevealBtn();
548	    updateRoundInfo();
549	    renderScoreboard();
550	    startTimer();
551	}
552	
553	// ===== Fogos =====
554	let fireworksTimeout;
555	
556	function triggerFireworks() {
557	    fireworksCanvas.style.display = 'block';
558	    fireworkEngine.start();
559	
560	    const w = window.innerWidth;
561	    const h = window.innerHeight;
562	    const explosionCount = 10;
563	    for (let i = 0; i < explosionCount; i++) {
564	        setTimeout(() => {
565	            if (fireworkEngine.explosions.length < FireworkConfig.maxExplosions) {
566	                const x = Math.random() * w;
567	                const y = Math.random() * h * 0.7;
568	                const color = FireworkConfig.colors[Math.floor(Math.random() * FireworkConfig.colors.length)];
569	                fireworkEngine.createExplosion(x, y, color);
570	                fireworkEngine.createFallingLines(x, y, color);
571	            }
572	        }, Math.random() * 2000);
573	    }
574	
575	    clearTimeout(fireworksTimeout);
576	    fireworksTimeout = setTimeout(() => {
577	        fireworkEngine.stop();
578	        fireworksCanvas.style.display = 'none';
579	    }, 5000);
580	}
581	
582	// ===== Configurações de UI =====
583	function applyTheme() {
584	    document.documentElement.setAttribute('data-theme', state.theme);
585	    themeToggle.textContent = state.theme === 'dark' ? 'Tema Claro' : 'Tema Escuro';
586	    themeToggle.setAttribute('aria-pressed', state.theme === 'dark' ? 'true' : 'false');
587	}
588	
589	function applySoundToggle() {
590	    soundToggle.textContent = state.soundOn ? 'Som: Ligado' : 'Som: Desligado';
591	    soundToggle.setAttribute('aria-pressed', state.soundOn ? 'true' : 'false');
592	}
593	
594	function setActiveBtns(group, value, attr) {
595	    group.querySelectorAll('button').forEach(btn => {
596	        btn.classList.toggle('active', btn.getAttribute(attr) === value);
597	    });
598	}
599	
600	// ===== Inicialização =====
601	document.addEventListener('DOMContentLoaded', () => {
602	    buildCategoryOptions();
603	    categorySelect.value = state.category;
604	
605	    setActiveBtns(document.getElementById('modeGroup'), state.mode, 'data-mode');
606	    setActiveBtns(document.getElementById('difficultyGroup'), state.difficulty, 'data-diff');
607	    applyTheme();
608	    applySoundToggle();
609	
610	    // Modo
