// Firework Engine for Windows Solitaire-style animation
class FireworkEngine {
    constructor() {
        this.explosions = [];
        this.particles = [];
        this.canvas = null;
        this.ctx = null;
        this.running = false;
    }

    init(canvasId) {
        this.canvas = document.getElementById(canvasId);
        this.ctx = this.canvas.getContext('2d');
        this.resize();
        window.addEventListener('resize', () => this.resize());
    }

    resize() {
        if (this.canvas) {
            this.canvas.width = window.innerWidth;
            this.canvas.height = window.innerHeight;
        }
    }

    // Create explosion at position
    createExplosion(x, y, color) {
        const explosion = {
            x: x,
            y: y,
            color: color,
            particles: [],
            life: 100,
            maxParticles: 100
        };

        // Create particle system for explosion
        for (let i = 0; i < explosion.maxParticles; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = Math.random() * 5 + 2;
            const size = Math.random() * 3 + 1;

            explosion.particles.push({
                x: x,
                y: y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                size: size,
                life: 100,
                maxLife: 100
            });
        }

        this.explosions.push(explosion);
    }

    // Create falling line effect from explosion point
    createFallingLines(x, y, color) {
        const lines = [];
        const numLines = Math.floor(Math.random() * 20) + 10;

        for (let i = 0; i < numLines; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = Math.random() * 3 + 1;
            const length = Math.random() * 50 + 20;

            lines.push({
                x: x,
                y: y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                length: length,
                color: color,
                life: 100,
                maxLife: 100
            });
        }

        this.particles.push(...lines);
    }

    update() {
        // Update explosions
        for (let i = this.explosions.length - 1; i >= 0; i--) {
            const explosion = this.explosions[i];
            explosion.life--;

            // Update particles in explosion
            for (let j = explosion.particles.length - 1; j >= 0; j--) {
                const p = explosion.particles[j];
                p.x += p.vx;
                p.y += p.vy;
                p.life--;

                if (p.life <= 0) {
                    explosion.particles.splice(j, 1);
                }
            }

            // Remove explosion when all particles are gone
            if (explosion.particles.length === 0 && explosion.life <= 0) {
                this.explosions.splice(i, 1);
            }
        }

        // Update falling lines
        for (let i = this.particles.length - 1; i >= 0; i--) {
            const line = this.particles[i];
            line.x += line.vx;
            line.y += line.vy;
            line.life--;

            if (line.life <= 0) {
                this.particles.splice(i, 1);
            }
        }
    }

    render() {
        // Clear canvas
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        // Render explosions
        for (const explosion of this.explosions) {
            for (const particle of explosion.particles) {
                const alpha = particle.life / particle.maxLife;
                this.ctx.fillStyle = explosion.color.replace(')', `, ${alpha})`).replace('rgb', 'rgba');
                this.ctx.beginPath();
                this.ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
                this.ctx.fill();
            }
        }

        // Render falling lines
        for (const line of this.particles) {
            const alpha = line.life / line.maxLife;
            this.ctx.strokeStyle = line.color.replace(')', `, ${alpha})`).replace('rgb', 'rgba');
            this.ctx.lineWidth = 2;
            this.ctx.beginPath();
            this.ctx.moveTo(line.x, line.y);
            this.ctx.lineTo(line.x + Math.cos(Math.atan2(line.vy, line.vx)) * line.length, 
                          line.y + Math.sin(Math.atan2(line.vy, line.vx)) * line.length);
            this.ctx.stroke();
        }
    }

    // Main animation loop
    animate() {
        if (!this.running) return;
        this.update();
        this.render();
        requestAnimationFrame(() => this.animate());
    }

    // Start the animation loop (no-op if already running)
    start() {
        if (this.running) return;
        this.running = true;
        this.animate();
    }

    // Stop the animation loop
    stop() {
        this.running = false;
    }
}

// Firework Configuration Parameters
const FireworkConfig = {
    // General settings
    maxExplosions: 10,
    explosionFrequency: 50, // frames between explosions

    // Particle settings
    particleSizeRange: [1, 5],
    particleSpeedRange: [1, 8],
    particleLifeRange: [50, 150],

    // Line settings
    lineLengthRange: [20, 70],
    lineSpeedRange: [0.5, 4],
    lineLifeRange: [50, 150],

    // Color palette for fireworks
    colors: [
        'rgb(255, 50, 50)',   // Red
        'rgb(50, 255, 50)',   // Green
        'rgb(50, 50, 255)',   // Blue
        'rgb(255, 255, 50)',  // Yellow
        'rgb(255, 50, 255)',  // Magenta
        'rgb(50, 255, 255)',  // Cyan
        'rgb(255, 150, 50)'   // Orange
    ],

    // Animation settings
    frameRate: 60,
    canvasWidth: window.innerWidth,
    canvasHeight: window.innerHeight
};

