:root {
    --bg-gradient: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    --surface: rgba(255, 255, 255, 0.92);
    --panel: rgba(0, 0, 0, 0.04);
    --text: #333;
    --text-soft: #667;
    --border: #334;
    --key-bg: #fff;
    --key-hover: #f0f0f0;
    --correct: #2e9e4f;
    --incorrect: #e5484d;
    --accent: #ff9800;
    --accent-dark: #f57c00;
    --sweat: #56b6f0;
    --shadow: rgba(0, 0, 0, 0.3);
}

[data-theme="dark"] {
    --bg-gradient: linear-gradient(135deg, #1a1a2e 0%, #16213e 55%, #243b55 100%);
    --surface: rgba(30, 34, 52, 0.96);
    --panel: rgba(255, 255, 255, 0.05);
    --text: #eaeaea;
    --text-soft: #a8aebe;
    --border: #9aa0b5;
    --key-bg: #2a2f45;
    --key-hover: #343a55;
    --accent: #ffb74d;
    --accent-dark: #ff9800;
    --shadow: rgba(0, 0, 0, 0.6);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html, body {
    height: 100%;
}

body {
    font-family: 'Segoe UI', 'Arial', sans-serif;
    background: var(--bg-gradient);
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 16px;
    transition: background 0.3s ease;
}

.container {
    background: var(--surface);
    border-radius: 18px;
    padding: 24px 28px;
    box-shadow: 0 16px 45px var(--shadow);
    max-width: 1100px;
    width: 100%;
    height: fit-content;
}

/* ---------- Topbar ---------- */
.topbar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-bottom: 14px;
    border-bottom: 2px solid var(--panel);
    margin-bottom: 16px;
}

h1 {
    color: var(--text);
    font-size: 1.9em;
    letter-spacing: 1px;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.1);
}

.topbar-settings {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    align-items: center;
}

.btn-group {
    display: flex;
    gap: 4px;
    background: var(--key-bg);
    padding: 4px;
    border-radius: 10px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.12);
}

.toggle-btn {
    padding: 6px 12px;
    font-size: 0.85em;
    border: none;
    background: transparent;
    color: var(--text);
    border-radius: 7px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.toggle-btn:hover {
    background: var(--key-hover);
}

.toggle-btn.active,
.toggle-btn[aria-pressed="true"] {
    background: var(--accent);
    color: #fff;
    font-weight: bold;
}

.category-select {
    padding: 7px 10px;
    font-size: 0.85em;
    border: none;
    border-radius: 7px;
    background: var(--key-bg);
    color: var(--text);
    cursor: pointer;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.12);
}

/* ---------- Scoreboard ---------- */
.scoreboard {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: center;
    margin-bottom: 18px;
}

.score-card {
    background: var(--panel);
    border-radius: 12px;
    padding: 10px 18px;
    min-width: 110px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.12);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.score-card.turn {
    transform: scale(1.06);
    box-shadow: 0 0 0 3px var(--accent), 0 4px 12px rgba(0, 0, 0, 0.25);
}

.score-card .name {
    font-weight: bold;
    font-size: 0.85em;
    color: var(--text-soft);
}

.score-card .score-value {
    font-size: 1.5em;
    font-weight: bold;
    color: var(--accent);
}

/* ---------- Grid principal ---------- */
.game-grid {
    display: grid;
    grid-template-columns: 340px 1fr;
    gap: 20px;
    align-items: start;
}

.gallows-panel {
    background: var(--panel);
    border-radius: 16px;
    padding: 18px 10px 10px;
    display: flex;
    justify-content: center;
    position: sticky;
    top: 8px;
}

#hangmanSvg {
    color: var(--text);
    width: 100%;
    max-width: 230px;
    height: auto;
    display: block;
}

.play-panel {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

/* ---------- Game info ---------- */
.status-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 8px;
}

.guesses-left {
    font-size: 1.15em;
    font-weight: bold;
    color: var(--text);
}

.guesses-left span {
    color: var(--accent);
    font-size: 1.15em;
}

.round-info {
    font-size: 0.9em;
    color: var(--text-soft);
}

#timerText {
    font-weight: bold;
}

.word-display {
    font-size: 2.6em;
    letter-spacing: 10px;
    margin: 14px 0 4px;
    min-height: 1.1em;
    color: var(--text);
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.08);
    font-weight: bold;
    word-break: break-all;
}

/* ---------- Forca / stickman ---------- */
.hangman-part {
    stroke: currentColor;
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    transition: stroke-dashoffset 0.5s ease;
}

.hangman-part.drawn {
    stroke-dashoffset: 0;
}

#head { fill: transparent; }

#face {
    opacity: 0;
    transition: opacity 0.4s ease 0.35s;
}

#face.visible {
    opacity: 1;
}

#face .pupil {
    fill: currentColor;
    transition: transform 0.35s ease;
}

#face .eye {
    transition: opacity 0.08s steps(1);
}

#face .eye.blink {
    opacity: 0;
}

#face.tired .pupil {
    transform: translateY(1.5px);
}

#face.dead .pupil {
    display: none;
}

.dead-x {
    display: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
}

#face.dead .dead-x {
    display: block;
}

#mouth {
    transition: d 0.3s ease;
}

#face.talking #mouth {
    animation: talking 0.28s ease-in-out infinite alternate;
}

@keyframes talking {
    from { d: path("M133 90 Q140 96 147 90"); }
    to   { d: path("M133 91 Q140 99 147 91"); }
}

#sweat {
    opacity: 0;
    fill: var(--sweat);
    transform-origin: 159px 68px;
}

#face.fear .sweat {
    animation: sweat 1.4s ease-in-out infinite;
}

@keyframes sweat {
    0%   { opacity: 0; transform: translate(0, 0) scale(0.6); }
    30%  { opacity: 1; }
    100% { opacity: 0; transform: translate(4px, 14px) scale(1); }
}

/* ---------- Teclado ---------- */
.keyboard {
    display: grid;
    grid-template-rows: repeat(3, auto);
    gap: 8px;
    justify-content: center;
}

.row {
    display: flex;
    justify-content: center;
    gap: 6px;
    flex-wrap: wrap;
}

.key {
    min-width: 42px;
    min-height: 42px;
    padding: 2px;
    border: 2px solid var(--border);
    background: var(--key-bg);
    color: var(--text);
    border-radius: 9px;
    font-size: 1.15em;
    font-weight: bold;
    cursor: pointer;
    transition: all 0.18s ease;
    box-shadow: 0 3px 6px rgba(0, 0, 0, 0.18);
}

.key:hover:not(:disabled) {
    transform: translateY(-3px);
    box-shadow: 0 6px 10px rgba(0, 0, 0, 0.28);
    background: var(--key-hover);
}

.key:disabled {
    opacity: 0.45;
    cursor: default;
    transform: none;
    box-shadow: none;
}

.key.correct {
    background: var(--correct);
    color: white;
    border-color: var(--correct);
    opacity: 1;
}

.key.incorrect {
    background: var(--incorrect);
    color: white;
    border-color: var(--incorrect);
    opacity: 1;
}

/* ---------- Dica / mensagem ---------- */
.hint-bar {
    display: flex;
    gap: 10px;
    justify-content: center;
}

#hintBtn, #revealBtn {
    padding: 8px 16px;
    font-size: 0.95em;
    background: var(--key-bg);
    color: var(--text);
    border: 2px solid var(--border);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
}

#hintBtn:hover:not(:disabled), #revealBtn:hover:not(:disabled) {
    background: var(--key-hover);
    transform: translateY(-2px);
}

#hintBtn:disabled, #revealBtn:disabled {
    opacity: 0.45;
    cursor: default;
}

.hint-text {
    min-height: 1.4em;
    font-style: italic;
    color: var(--text-soft);
}

.message {
    font-size: 1.35em;
    min-height: 1.5em;
    font-weight: bold;
    color: var(--text);
}

/* ---------- Botão novo jogo ---------- */
#newGameBtn {
    align-self: center;
    padding: 12px 34px;
    font-size: 1.05em;
    font-weight: bold;
    background: var(--accent);
    color: white;
    border: none;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.25s ease;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.25);
}

#newGameBtn:hover {
    background: var(--accent-dark);
    transform: translateY(-2px);
    box-shadow: 0 7px 14px rgba(0, 0, 0, 0.3);
}

#fireworksCanvas {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1000;
    display: none;
}

/* ---------- Responsivo ---------- */
@media (max-width: 860px) {
    .topbar {
        flex-direction: column;
        align-items: flex-start;
    }

    .game-grid {
        grid-template-columns: 1fr;
    }

    .gallows-panel {
        position: static;
        padding-bottom: 6px;
    }

    #hangmanSvg { max-width: 190px; }

    .word-display {
        font-size: 2em;
        letter-spacing: 6px;
    }
}

@media (max-width: 480px) {
    .container { padding: 16px; }
    h1 { font-size: 1.5em; }

    .key {
        min-width: 32px;
        min-height: 36px;
        font-size: 1em;
    }

    .row { gap: 4px; }
}

